async hidePaymentInstallment(
  installmentId: number,
  body: any,
  currentUser: any,
) {
  const roles = currentUser?.roles || [];

  const canHide =
  roles.includes('OWNER') ||
  roles.includes('MARKETING_HEAD') ||
  roles.includes('PROJECT_MANAGER') ||
  roles.includes('PAYMENT_MANAGER') ||
  roles.includes('ACCOUNT_MANAGER');

  if (!canHide) {
    throw new ForbiddenException(
      'You are not allowed to hide payment entries',
    );
  }

  const installment =
    await this.projectPaymentInstallmentRepository.findOne({
      where: { id: installmentId },
    });

  if (!installment) {
    throw new NotFoundException('Payment installment not found');
  }

  installment.isHidden = true;
  installment.hiddenAt = new Date();
  installment.hiddenBy = currentUser?.id || currentUser?.userId || null;
  installment.hiddenByName = currentUser?.name || currentUser?.email || '';
  installment.hiddenReason = body?.reason || 'Hidden by user';

  return this.projectPaymentInstallmentRepository.save(installment);
}

async hideProject(id: number, body: any, user: any) {
  const roles = Array.isArray(user?.roles) ? user.roles : [];

  const canHide =
    roles.includes('OWNER') ||
    roles.includes('MARKETING_HEAD') ||
    roles.includes('PROJECT_MANAGER');

  if (!canHide) {
    throw new ForbiddenException('You are not allowed to hide projects');
  }

  const project = await this.projectRepository.findOne({
    where: { id },
  });

  if (!project) {
    throw new NotFoundException('Project not found');
  }

  project.isHidden = true;
  project.hiddenAt = new Date();
  project.hiddenBy = user?.id || user?.userId || null;
  project.hiddenByName = user?.name || user?.email || '';
  project.hiddenReason = body?.reason || 'Hidden by user';

  return this.projectRepository.save(project);
}

async getHiddenProjects(
  user: any,
  query: any = {},
) {
  const roles = Array.isArray(user?.roles)
    ? user.roles
    : [];

  const canViewHidden =
    roles.includes('OWNER') ||
    roles.includes('PROJECT_MANAGER');

  if (!canViewHidden) {
    throw new ForbiddenException(
      'You are not allowed to view hidden projects',
    );
  }

  const page = Math.max(
    Number(query?.page || 1),
    1,
  );

  const limit = Math.min(
    Math.max(Number(query?.limit || 20), 1),
    100,
  );

  const skip = (page - 1) * limit;

  const search = String(
    query?.search || '',
  ).trim();

  const qb =
    this.projectRepository
      .createQueryBuilder('project')
      .where(
        'project.isHidden = :isHidden',
        {
          isHidden: true,
        },
      );

  if (search) {
    qb.andWhere(
      `(
        CAST(project.id AS TEXT) ILIKE :search
        OR project.customerName ILIKE :search
        OR project.customerPhone ILIKE :search
        OR project.electricityKNumber ILIKE :search
        OR project.projectOwnerName ILIKE :search
        OR project.solarFranchiseName ILIKE :search
        OR project.hiddenByName ILIKE :search
        OR project.hiddenReason ILIKE :search
      )`,
      {
        search: `%${search}%`,
      },
    );
  }

  const [data, total] =
    await qb
      .orderBy(
        'project.hiddenAt',
        'DESC',
      )
      .addOrderBy(
        'project.updatedAt',
        'DESC',
      )
      .skip(skip)
      .take(limit)
      .getManyAndCount();

  return {
    data,
    total,
    page,
    limit,
    totalPages:
      Math.ceil(total / limit) || 1,
  };
}

async restoreProject(id: number, body: any, user: any) {
  const roles = Array.isArray(user?.roles) ? user.roles : [];

  const canRestore =
    roles.includes('OWNER') ||
    roles.includes('PROJECT_MANAGER');

  if (!canRestore) {
    throw new ForbiddenException(
      'You are not allowed to restore projects',
    );
  }

  const project = await this.projectRepository.findOne({
    where: { id },
  });

  if (!project) {
    throw new NotFoundException('Project not found');
  }

  project.isHidden = false;
  project.hiddenAt = null as any;
  project.hiddenBy = null as any;
  project.hiddenByName = null as any;
  project.hiddenReason = null as any;

  return this.projectRepository.save(project);
}

async createExecutionActivity(
  data: Partial<ProjectExecutionActivity>,
  user: any,
) {
  if (!data.projectId) {
    throw new BadRequestException(
      'Project ID is required',
    );
  }

  if (!data.activityType) {
    throw new BadRequestException(
      'Activity type is required',
    );
  }

  let inspectionDeadline: Date | null = null;

  if (
    data.activityType ===
      ProjectExecutionActivityType.STRUCTURE_INSPECTION ||
    data.activityType ===
      ProjectExecutionActivityType.PILLAR_INSPECTION
  ) {
    inspectionDeadline = new Date();

    inspectionDeadline.setDate(
      inspectionDeadline.getDate() + 1,
    );
  }

  if (
    data.activityType ===
    ProjectExecutionActivityType.GENERATION_INSPECTION
  ) {
    inspectionDeadline = new Date();

    inspectionDeadline.setDate(
      inspectionDeadline.getDate() + 3,
    );
  }

  const activity =
    this.projectExecutionActivityRepository.create({
      projectId: Number(data.projectId),

      activityType:
        data.activityType as ProjectExecutionActivityType,

      status:
        (data.status as ProjectExecutionActivityStatus) ||
        ProjectExecutionActivityStatus.PENDING,

      scheduledDate: data.scheduledDate
        ? new Date(data.scheduledDate)
        : null,

      completedDate: data.completedDate
        ? new Date(data.completedDate)
        : null,

      inspectionDeadline,

      proofRequired:
        data.proofRequired === true,

      remarks: data.remarks || '',

      assignedTo: data.assignedTo || null,
      assignedToName:
        data.assignedToName || '',

      createdBy: user?.id || null,
      createdByName: user?.name || '',
    } as Partial<ProjectExecutionActivity>);

  const savedActivity =
  await this
    .projectExecutionActivityRepository
    .save(activity);

if (
  savedActivity.status ===
    ProjectExecutionActivityStatus.COMPLETED
) {
  const achievedAt =
    savedActivity.completedDate
      ? new Date(
          savedActivity.completedDate,
        )
      : new Date();

  await this
    .recordProjectTimelineEventIfMissing({
      projectId:
        Number(
          savedActivity.projectId,
        ),

      module:
        ProjectTimelineModule.EXECUTION,

      milestone:
        savedActivity.activityType,

      achievedAt,

      sourceId:
        Number(savedActivity.id),

      recordedBy:
        user?.id ||
        user?.userId ||
        null,

      recordedByName:
        user?.name ||
        user?.email ||
        '',
    });
}

return savedActivity;
}

