async saveProjectSubsidyDetail(
  projectId: number,
  body: any,
  user: any,
) {
  const project = await this.projectRepository.findOne({
    where: { id: projectId },
  });

  if (!project) {
    throw new NotFoundException('Project not found');
  }

  let detail =
    await this.projectSubsidyDetailRepository.findOne({
      where: { projectId },
      order: {
        createdAt: 'DESC',
      },
    });

  if (!detail) {
    detail = this.projectSubsidyDetailRepository.create({
      projectId,
    });
  }

  const previousSubsidyStatus =
  detail?.status || null;

const previousDcrCertificateReady =
  detail?.dcrCertificateReady === true;

  Object.assign(detail, {
    status: body.status || detail.status,
    dcrCertificateReady:
      body.dcrCertificateReady === true ||
      body.dcrCertificateReady === 'true',
    panelWarrantyReceived:
      body.panelWarrantyReceived === true ||
      body.panelWarrantyReceived === 'true',
    inverterWarrantyReceived:
      body.inverterWarrantyReceived === true ||
      body.inverterWarrantyReceived === 'true',
    vendorAgreementReady:
      body.vendorAgreementReady === true ||
      body.vendorAgreementReady === 'true',
    wcrReady:
      body.wcrReady === true ||
      body.wcrReady === 'true',
    portalSubmissionDate: body.portalSubmissionDate
      ? new Date(body.portalSubmissionDate)
      : null,
    subsidyRequestedDate: body.subsidyRequestedDate
      ? new Date(body.subsidyRequestedDate)
      : null,
    subsidyDisbursedDate: body.subsidyDisbursedDate
      ? new Date(body.subsidyDisbursedDate)
      : null,
    subsidyAmount: this.toNumberOrZero(body.subsidyAmount),
    remarks: body.remarks || '',
    updatedBy: user?.id || null,
    updatedByName: user?.name || user?.email || '',
  });

  const savedDetail =
  await this
    .projectSubsidyDetailRepository
    .save(detail);

const currentSubsidyStatus =
  savedDetail.status || null;

if (
  currentSubsidyStatus &&
  currentSubsidyStatus !==
    previousSubsidyStatus
) {
  let achievedAt:
    Date | null = null;

  switch (
    currentSubsidyStatus
  ) {
    case ProjectSubsidyStatus
      .SUBMISSION_DONE:
      achievedAt =
        savedDetail
          .portalSubmissionDate
          ? new Date(
              savedDetail
                .portalSubmissionDate,
            )
          : null;
      break;

    case ProjectSubsidyStatus
      .SUBSIDY_REQUESTED:
      achievedAt =
        savedDetail
          .subsidyRequestedDate
          ? new Date(
              savedDetail
                .subsidyRequestedDate,
            )
          : null;
      break;

    case ProjectSubsidyStatus
      .SUBSIDY_DISBURSED:
      achievedAt =
        savedDetail
          .subsidyDisbursedDate
          ? new Date(
              savedDetail
                .subsidyDisbursedDate,
            )
          : null;
      break;

    default:
      achievedAt = null;
  }

  await this
    .recordProjectTimelineEventIfMissing({
      projectId:
        Number(projectId),

      module:
        ProjectTimelineModule
          .SUBSIDY,

      milestone:
        currentSubsidyStatus,

      achievedAt:
        achievedAt ||
        new Date(),

      sourceId:
        Number(
          savedDetail.id,
        ),

      recordedBy:
        user?.id ||
        user?.userId ||
        null,

      recordedByName:
        user?.name ||
        user?.email ||
        '',
    });
}

/*
 * DCR Certificate Ready is stored separately
 * as a boolean field.
 *
 * Record the first false -> true transition
 * so Timeline Tracking gets a genuine
 * achievement timestamp going forward.
 */
if (
  !previousDcrCertificateReady &&
  savedDetail.dcrCertificateReady ===
    true
) {
  await this
    .recordProjectTimelineEventIfMissing({
      projectId:
        Number(projectId),

      module:
        ProjectTimelineModule.SUBSIDY,

      milestone:
        ProjectSubsidyStatus
          .DCR_CERTIFICATE_READY,

      achievedAt:
        new Date(),

      sourceId:
        Number(savedDetail.id),

      recordedBy:
        user?.id ||
        user?.userId ||
        null,

      recordedByName:
        user?.name ||
        user?.email ||
        '',
    });
}

return savedDetail;
}

