async saveProjectElectricityDetail(
  projectId: number,
  body: any,
  user: any,
) {
  const project = await this.projectRepository.findOne({
    where: { id: projectId },
  });

  if (!project) {
    throw new NotFoundException('Project not found');
  }

  let detail =
    await this.projectElectricityDetailRepository.findOne({
      where: { projectId },
      order: {
        createdAt: 'DESC',
      },
    });

  if (!detail) {
    detail =
      this.projectElectricityDetailRepository.create({
        projectId,
      });
  }

  const previousElectricityStatus =
  detail?.status || null;

  Object.assign(detail, {
    discomName: body.discomName || '',
    status: body.status || detail.status,
    fileSubmissionDate: body.fileSubmissionDate
      ? new Date(body.fileSubmissionDate)
      : null,
    siteVisitDate: body.siteVisitDate
      ? new Date(body.siteVisitDate)
      : null,
    demandDepositDate: body.demandDepositDate
      ? new Date(body.demandDepositDate)
      : null,
    demandDepositAmount: this.toNumberOrZero(
      body.demandDepositAmount,
    ),
    meterTestingDate: body.meterTestingDate
      ? new Date(body.meterTestingDate)
      : null,
    netMeterInstallationDate:
      body.netMeterInstallationDate
        ? new Date(body.netMeterInstallationDate)
        : null,
    remarks: body.remarks || '',
    updatedBy: user?.id || null,
    updatedByName:
      user?.name || user?.email || '',
  });

  const savedDetail =
  await this
    .projectElectricityDetailRepository
    .save(detail);

const currentElectricityStatus =
  savedDetail.status || null;

if (
  currentElectricityStatus &&
  currentElectricityStatus !==
    previousElectricityStatus
) {
  let achievedAt:
    Date | null = null;

  switch (
    currentElectricityStatus
  ) {
    case ProjectElectricityStatus
      .FILE_SUBMITTED:
      achievedAt =
        savedDetail
          .fileSubmissionDate
          ? new Date(
              savedDetail
                .fileSubmissionDate,
            )
          : null;
      break;

    case ProjectElectricityStatus
      .SITE_VISIT_DONE:
      achievedAt =
        savedDetail
          .siteVisitDate
          ? new Date(
              savedDetail
                .siteVisitDate,
            )
          : null;
      break;

    case ProjectElectricityStatus
      .DEMAND_DEPOSITED:
      achievedAt =
        savedDetail
          .demandDepositDate
          ? new Date(
              savedDetail
                .demandDepositDate,
            )
          : null;
      break;

    case ProjectElectricityStatus
      .METER_TESTING_DONE:
      achievedAt =
        savedDetail
          .meterTestingDate
          ? new Date(
              savedDetail
                .meterTestingDate,
            )
          : null;
      break;

    case ProjectElectricityStatus
      .NET_METER_INSTALLED:
      achievedAt =
        savedDetail
          .netMeterInstallationDate
          ? new Date(
              savedDetail
                .netMeterInstallationDate,
            )
          : null;
      break;

    default:
      achievedAt = null;
  }

  await this
    .recordProjectTimelineEventIfMissing({
      projectId:
        Number(projectId),

      module:
        ProjectTimelineModule
          .ELECTRICITY,

      milestone:
        currentElectricityStatus,

      achievedAt:
        achievedAt ||
        new Date(),

      sourceId:
        Number(
          savedDetail.id,
        ),

      recordedBy:
        user?.id ||
        user?.userId ||
        null,

      recordedByName:
        user?.name ||
        user?.email ||
        '',
    });
}

return savedDetail;
}

async assignContractorToProject(body: any, user: any) {
  const roles = Array.isArray(user?.roles) ? user.roles : [];

  const currentUserId = Number(user?.id || user?.sub);
const isSolarFranchise = roles.includes('SOLAR_FRANCHISE');

  if (
  !roles.includes('OWNER') &&
  !roles.includes('PROJECT_MANAGER') &&
  !roles.includes('SOLAR_FRANCHISE')
) {
  throw new ForbiddenException(
    'Only owner, project manager, or solar franchise can assign contractor',
  );
}

  const projectId = Number(body?.projectId);
  const contractorId = Number(body?.contractorId);

  if (!projectId) {
    throw new BadRequestException('Project ID is required');
  }

  if (!contractorId) {
    throw new BadRequestException('Contractor is required');
  }

  const project = await this.projectRepository.findOne({
    where: { id: projectId },
  });

  if (!project) {
    throw new NotFoundException('Project not found');
  }

  if (isSolarFranchise && Number(project.projectOwnerId) !== currentUserId) {
  throw new ForbiddenException(
    'You can assign contractor only for your own franchise project',
  );
}

  const assignment =
    this.projectContractorAssignmentRepository.create({
      projectId,
      contractorId,
      contractorName: body?.contractorName || '',
      contractorPhone: body?.contractorPhone || '',
      workScope:
  body?.workScope ||
  ProjectContractorWorkScope.FULL_PROJECT,

assignedWorkItems: Array.isArray(body?.assignedWorkItems)
  ? body.assignedWorkItems
      .map((item: any) => String(item).trim())
      .filter(Boolean)
  : [],
      scheduledDate: body?.scheduledDate
        ? new Date(body.scheduledDate)
        : undefined,
      amount: this.toNumberOrZero(body?.amount),
      status:
        body?.status ||
        ProjectContractorWorkStatus.ASSIGNED,
      remarks: body?.remarks || '',
      assignedBy: user?.id || user?.userId || null,
      assignedByName:
        user?.name || user?.email || '',
    });

  return this.projectContractorAssignmentRepository.save(
    assignment,
  );
}

